package com.chronos.integration.model; import com.chronos.model.pojo.BaseEntity; import java.time.LocalDateTime; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="int_sync_job") @Getter @Setter public class SyncJob extends BaseEntity { @Column(nullable=false,length=160) private String name; @Column(name="connector_id",nullable=false,length=64) private String connectorId; @Column(name="cron_expression",nullable=false,length=100) private String cronExpression; @Column(nullable=false,length=20) private String status="ENABLED"; @Column(name="request_path",nullable=false,length=500) private String requestPath; @Column(name="idempotency_key_template",length=300) private String idempotencyKeyTemplate; @Column(name="lease_owner",length=120) private String leaseOwner; @Column(name="lease_until") private LocalDateTime leaseUntil; }
